#include <bits/stdc++.h>
using namespace std;

ListNode* deleteDuplicates(ListNode* head) {
    unordered_set<int> seen;
    ListNode dummy(0, head);
    ListNode* prev = &dummy;
    ListNode* node = head;
    while (node) {
        if (seen.count(node->val)) {                                            // this value has already appeared somewhere earlier
            prev->next = node->next;                                              // skip this duplicate node entirely
        } else {
            seen.insert(node->val);
            prev = node;
        }
        node = node->next;
    }
    return dummy.next;
}

int main() {
    ListNode* head = new ListNode(1, new ListNode(1, new ListNode(2, new ListNode(3, new ListNode(3)))));
    ListNode* result = deleteDuplicates(head);
    while (result) { cout << result->val << " "; result = result->next; }
    cout << endl;
    return 0;
}

